package org.jlab.paw;

import java.util.*;
import java.util.regex.*;

/** Fixed numeric Fortran input descriptors, nested repetition and positioning. */
final class FortranRowFormat {
    record Field(char type,int width,int decimals,int scale){}
    final List<Field>fields=new ArrayList<>();String source;int position,scale;
    FortranRowFormat(String format){source=format.strip().toUpperCase(Locale.ROOT);if(!source.startsWith("(")||!source.endsWith(")"))throw new IllegalArgumentException("Fixed format must be parenthesized, e.g. (3F10.3)");position=1;parse();if(position!=source.length())throw new IllegalArgumentException("Unexpected format text");if(fields.stream().noneMatch(f->"IFEDG".indexOf(f.type)>=0))throw new IllegalArgumentException("Format requires numeric fields");}
    private int number(int fallback){int start=position;while(position<source.length()&&Character.isDigit(source.charAt(position)))position++;return start==position?fallback:Integer.parseInt(source.substring(start,position));}
    private void parse(){while(position<source.length()){char ch=source.charAt(position);if(ch==')'){position++;return;}if(ch==','||Character.isWhitespace(ch)){position++;continue;}int sign=1;if(ch=='-'||ch=='+'){sign=ch=='-'?-1:1;position++;}int repeat=number(1);if(position>=source.length())break;ch=source.charAt(position++);if(ch=='P'){scale=sign*repeat;continue;}if(repeat<1||repeat>10000||sign<0)throw new IllegalArgumentException("Format repeat 1..10000");if(ch=='('){int start=fields.size();parse();List<Field>group=new ArrayList<>(fields.subList(start,fields.size()));for(int r=1;r<repeat;r++)fields.addAll(group);continue;}
            if(ch=='X'){fields.add(new Field('X',repeat,0,0));continue;}if(ch=='T'){char mode='T';if(position<source.length()&&(source.charAt(position)=='L'||source.charAt(position)=='R'))mode=source.charAt(position++);fields.add(new Field(mode,number(1),0,0));continue;}if("IFEDG".indexOf(ch)<0)throw new IllegalArgumentException("Unsupported fixed format descriptor: "+ch);int width=number(0),decimals=0;if(position<source.length()&&source.charAt(position)=='.'){position++;decimals=number(0);}if(position<source.length()&&source.charAt(position)=='E'){position++;number(0);}if(width<1||width>100000||decimals>300)throw new IllegalArgumentException("Invalid numeric field width/precision");for(int r=0;r<repeat;r++)fields.add(new Field(ch,width,decimals,scale));if(fields.size()>100000)throw new IllegalArgumentException("Format too large");}throw new IllegalArgumentException("Unclosed fixed format group");}
    List<String>read(String line){int offset=0;List<String>values=new ArrayList<>();for(Field f:fields){if(f.type=='X'||f.type=='R'){offset+=f.width;continue;}if(f.type=='L'){offset=Math.max(0,offset-f.width);continue;}if(f.type=='T'){offset=f.width-1;continue;}if(offset+f.width>line.length())throw new IllegalArgumentException("Short fixed-format input row");String s=line.substring(offset,offset+f.width).replace(" ","").toUpperCase(Locale.ROOT).replace('D','E');offset+=f.width;if(s.isBlank())s="0";s=s.replaceAll("(?<=[0-9.])([+-][0-9]+)$","E$1");double value=Double.parseDouble(s);if(!s.contains(".")&&!s.contains("E")&&f.type!='I')value/=Math.pow(10,f.decimals);if(!s.contains("E")&&f.type!='I')value/=Math.pow(10,f.scale);values.add(Double.toString(value));}return values;}
}
